  last_checked_at text,
  last_result     text CHECK (last_result IS NULL OR last_result IN ('ok','not_found','mismatch','resolver_error')),
  verified_at     text,
  created_at      text NOT NULL,
  UNIQUE (org_id, id),
  UNIQUE (site_id, token),
